import XCTest
import GRDB
@testable import DefterXMobile
final class OfflineRepositoryTests:XCTestCase{func testMutationAndOperationAreAtomic()async throws{let database=try AppDatabase(inMemory:true),repository=LocalTransactionRepository(database:database),book=UUID(),operation=UUID();let item=FinanceTransaction(id:UUID(),bookId:book,type:.expense,title:"Market",amount:try Money("100.25"),currencyCode:"TRY",accountId:UUID(),targetAccountId:nil,categoryId:UUID(),contactId:nil,transactionDate:.now,dueDate:nil,details:nil,clientOperationId:operation,serverVersion:nil,syncState:.pending);try await repository.createOffline(item);let counts=try await database.writer.read{db in(try Int.fetchOne(db,sql:"SELECT count(*) FROM local_transactions"),try Int.fetchOne(db,sql:"SELECT count(*) FROM sync_operations"))};XCTAssertEqual(counts.0,1);XCTAssertEqual(counts.1,1);let pending=try await repository.pendingOperations(limit:10);XCTAssertEqual(pending.first?.operationId,operation)}}
